mapper.select:
SELECT count(*) FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_SHIP ship USING (BOX_OID) JOIN (SELECT xfc.xm_OID, GROUP_CONCAT(DISTINCT fault.VALUE) AS faultCode FROM BASIL_ODS_PRD.XREF_FAULT_CODE xfc JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE GROUP BY xfc.xm_OID) fault USING (xm_OID)
mo.MC_OID = #{id}
AND
#{item}
AND
#{item}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND ship.SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
AND xm.STATUS = 113

SELECT ship.SHIP_DATE AS shipDate, part.PART_NUMBER_SHORT AS partNumber, msn.SERIAL_NUMBER AS serialNumber, mo.MO_OID AS rmaNumber, ship.TRACKING_NUMBER AS trackingNumber, xm.CUSTOMER_REPORTED_ISSUE_EXT AS reportedIssue, xm.TECH_NOTES AS techNotes, fault.faultCode, mc.CUSTOMER_ORGANIZATION as customerOrganization FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING (MC_OID) JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_SHIP ship USING (BOX_OID) JOIN (SELECT xfc.xm_OID, GROUP_CONCAT(DISTINCT fault.VALUE) AS faultCode FROM BASIL_ODS_PRD.XREF_FAULT_CODE xfc JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE GROUP BY xfc.xm_OID) fault USING (xm_OID)
mo.MC_OID = #{id}
AND
#{item}
AND
#{item}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND ship.SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
AND xm.STATUS = 113
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT count(*) FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID)
mo.MC_OID = #{id}
AND
#{item}
AND
#{item}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND xm.CUSTOMER_CONTACT_NEEDED = #{contact}
AND xm.STATUS = 108

SELECT xm.QUARANTINE_DATE as quarantineDate, part.PART_NUMBER_SHORT as partNumber, msn.SERIAL_NUMBER as serialNumber, mo.MO_OID as rmaNumber, sav.VALUE as customerContact, xm.TECH_NOTES as techNotes, fault.faultCode, parts.partsNeeded, mc.CUSTOMER_ORGANIZATION as customerOrganization FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING (MC_OID) JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) LEFT JOIN BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES sav ON sav.SAV_OID = xm.CUSTOMER_CONTACT_NEEDED LEFT JOIN (SELECT xfc.xm_OID, GROUP_CONCAT(DISTINCT fault.VALUE) AS faultCode FROM BASIL_ODS_PRD.XREF_FAULT_CODE xfc JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE GROUP BY xfc.xm_OID) fault USING (xm_OID) LEFT JOIN (SELECT fm.xm_OID, GROUP_CONCAT(DISTINCT TRIM(material.MATERIAL_DESCRIPTION) SEPARATOR ' | ') AS partsNeeded FROM (SELECT XM_OID, MM_OID FROM BASIL_ODS_PRD.FACT_MEASURE UNION SELECT XM_OID, MM_OID FROM BASIL_ODS_PRD.HIST_FACT_MEASURE WHERE MEASURE_OID = 9) fm JOIN BASIL_ODS_PRD.MASTER_MATERIAL material USING (MM_OID) GROUP BY fm.xm_OID) parts USING (xm_OID)
mo.MC_OID = #{id}
AND
#{item}
AND
#{item}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND xm.CUSTOMER_CONTACT_NEEDED = #{contact}
AND xm.STATUS = 108
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT part.PART_NUMBER_SHORT as partNumber, SUM(IF(xm.STATUS = 107, 1, 0)) AS inventory, SUM(IF(xm.STATUS = 110, 1, 0)) AS outForRepair, SUM(IF(xm.STATUS = 108, 1, 0)) AS quarantine, SUM(IF(xm.STATUS = 111, 1, 0)) AS awaitingQaCa, SUM(IF(xm.STATUS = 112, 1, 0)) AS readyToShip, COUNT(mo.MO_OID) AS TOTAL FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID)
xm.STATUS IN (107, 110, 108, 111, 112)
AND mo.MC_OID = #{id}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND
#{item}
AND
#{item}
GROUP BY part.PART_NUMBER_SHORT;

SELECT mo.MO_OID as rmaNumber, SUM(IF(xm.STATUS = 107, 1, 0)) AS inventory, SUM(IF(xm.STATUS = 110, 1, 0)) AS outForRepair, SUM(IF(xm.STATUS = 108, 1, 0)) AS quarantine, SUM(IF(xm.STATUS = 111, 1, 0)) AS awaitingQaCa, SUM(IF(xm.STATUS = 112, 1, 0)) AS readyToShip, COUNT(msn.SERIAL_NUMBER) AS total FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID)
xm.STATUS IN (107, 110, 108, 111, 112)
AND mo.MC_OID = #{id}
AND
#{item}
AND
#{item}
GROUP BY part.PART_NUMBER_SHORT, mo.MO_OID HAVING part.PART_NUMBER_SHORT = #{partNumber};

SELECT xm.XM_OID AS id, msn.SERIAL_NUMBER AS serialNumber, IF(xm.STATUS = 107, 1, 0) AS inventory, IF(xm.STATUS = 110, 1, 0) AS outForRepair, IF(xm.STATUS = 108, 1, 0) AS quarantine, IF(xm.STATUS = 111, 1, 0) AS awaitingQaCa, IF(xm.STATUS = 112, 1, 0) AS readyToShip
FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID)
mo.MC_OID = #{id}
AND xm.STATUS IN (107, 110, 108, 111, 112) AND part.PART_NUMBER_SHORT = #{partNumber} AND mo.MO_OID = #{rmaNumber}
AND
#{item}

SELECT part.PART_NUMBER_SHORT partNumber, mo.MO_OID rmaNumber, msn.SERIAL_NUMBER AS serialNumber, mc.CUSTOMER_ORGANIZATION as customerOrganization, IF(xm.STATUS = 107, 'Received', sav.VALUE) status FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) LEFT JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING (MC_OID) LEFT JOIN BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES sav ON sav.SAV_OID = xm.STATUS
xm.STATUS IN (107, 110, 108, 111, 112)
mo.MC_OID = #{id}
AND part.PART_NUMBER_SHORT LIKE CONCAT(#{partNumber},'%')
AND
#{item}
AND
#{item}
ORDER BY FIELD(xm.STATUS, 107, 110, 108, 111, 112), part.PART_NUMBER_SHORT
